import{_ as a,o as e,c as l,a2 as i}from"./chunks/framework.CWWEQfK7.js";const u=JSON.parse('{"title":"阅读文档、搜索项目和继续提问","description":"用生成文档、项目搜索和项目范围问答，从分析结果定位到可核对的源码。","frontmatter":{"page_id":"guide-read-search-chat","description":"用生成文档、项目搜索和项目范围问答，从分析结果定位到可核对的源码。"},"headers":[],"relativePath":"guide/read-search-chat.md","filePath":"guide/read-search-chat.md","lastUpdated":1786290726000}'),r={name:"guide/read-search-chat.md"};function d(o,t,s,h,c,n){return e(),l("div",null,[...t[0]||(t[0]=[i('<h1 id="阅读文档、搜索项目和继续提问" tabindex="-1">阅读文档、搜索项目和继续提问 <a class="header-anchor" href="#阅读文档、搜索项目和继续提问" aria-label="Permalink to &quot;阅读文档、搜索项目和继续提问&quot;">​</a></h1><p>一次分析完成后，你可以从三个入口理解项目：Docs 适合顺序阅读，Search 适合定位具体内容，Docs 中的问答适合把多个结果整理成带引用的回答。它们共享项目权限，但不是同一种查询方式。</p><h2 id="开始前确认产物存在" tabindex="-1">开始前确认产物存在 <a class="header-anchor" href="#开始前确认产物存在" aria-label="Permalink to &quot;开始前确认产物存在&quot;">​</a></h2><p>进入项目的 <strong>运行</strong> 页面，打开最近一次完整项目运行。状态应为 <code>completed</code> 或 <code>completed_with_warnings</code>，详情页应列出实际生成的文档。</p><p>如果运行失败、被取消，或没有生成任何文档，先处理运行警告和 Worker 错误。空的 Docs 页面不能通过重新加载浏览器变出内容。</p><h2 id="阅读生成文档" tabindex="-1">阅读生成文档 <a class="header-anchor" href="#阅读生成文档" aria-label="Permalink to &quot;阅读生成文档&quot;">​</a></h2><ol><li>打开项目的 <strong>Docs</strong> 页面。</li><li>从左侧列表选择一篇文档。文档按仓库和类别分组；项目包含多个仓库时，先确认选中了正确仓库。</li><li>使用文档内标题或右侧页内目录移动到需要的章节。</li><li>遇到源码引用时选择引用，打开来源预览。</li></ol><p>成功后，主区域会显示完整文档，当前章节会随阅读位置变化；选择有效引用后，会出现对应的仓库、路径、行号和源码片段。引用的作用是让你回到证据，不代表生成文字可以脱离源码单独作为事实。</p><p>文档中的内部链接会在 Ershu 文档间跳转。外部链接会先要求确认。Mermaid 图可以单独放大查看。</p><h2 id="搜索项目" tabindex="-1">搜索项目 <a class="header-anchor" href="#搜索项目" aria-label="Permalink to &quot;搜索项目&quot;">​</a></h2><p>打开项目的 <strong>Search</strong> 页面，输入查询内容，再选择一种方式：</p><ul><li><strong>关键词</strong>：按输入词查找内容，适合函数名、配置名和错误文字；</li><li><strong>语义</strong>：按含义查找，需要可用的向量模型（embedding）通道和语义索引；</li><li><strong>混合</strong>：组合语义和关键词结果；语义能力不可用时，可以明确降级到关键词。</li></ul><p>当前页面只提供一个可选的仓库筛选。你可以搜索全部仓库，也可以选择其中一个仓库。页面目前没有分支、语言、路径或内容类型筛选，不要按这些旧用法寻找控件。</p><p>选择搜索按钮后，成功结果会显示：</p><ul><li>返回数量；</li><li>内容片段；</li><li>代码、文档、API、README 或配置等结果类型；</li><li>来源路径和可用的行号；</li><li>展开后可见的语言、文档或章节信息。</li></ul><p>点击结果卡片可以展开完整片段。当前结果卡片不会自动跳到 Docs，也不会直接把结果带入问答。</p><h3 id="理解搜索降级" tabindex="-1">理解搜索降级 <a class="header-anchor" href="#理解搜索降级" aria-label="Permalink to &quot;理解搜索降级&quot;">​</a></h3><ul><li>语义方式不可用时，不应悄悄伪装成关键词搜索。请检查 embedding 通道和本次运行的搜索索引状态。</li><li>混合方式可以回退到关键词。页面会显示降级提示，说明当前结果没有完整使用语义能力。</li><li>关键词方式没有结果时，先换成源码中更独特的符号、配置名或错误文字，再检查仓库筛选是否选错。</li></ul><h2 id="在-docs-中发起项目问答" tabindex="-1">在 Docs 中发起项目问答 <a class="header-anchor" href="#在-docs-中发起项目问答" aria-label="Permalink to &quot;在 Docs 中发起项目问答&quot;">​</a></h2><p>问答入口位于 <strong>Docs</strong> 页面。打开问答面板并输入一个能被源码或文档验证的问题，例如：“这个项目如何加载配置？”</p><p>当前问答范围始终是整个项目：</p><ul><li>它不是只针对正在阅读的文档；</li><li>它也不是只针对当前章节；</li><li>项目包含多个仓库时，回答可能引用不同仓库的内容。</li></ul><p>发送后，面板会显示用户消息，并通过流式响应逐步补充回答。成功的回答会包含正文和可用引用；选择引用后，可像文档引用一样打开来源预览。</p><p>你还可以：</p><ul><li>新建会话；</li><li>打开已有会话；</li><li>按标题搜索会话；</li><li>删除不再需要的会话。</li></ul><p>如果回答显示仅检索结果或没有上下文，先确认项目确实有可检索内容，再检查可用模型通道。不要把没有引用、无法回到项目证据的回答当成已经核实的结论。</p><h2 id="选择合适的入口" tabindex="-1">选择合适的入口 <a class="header-anchor" href="#选择合适的入口" aria-label="Permalink to &quot;选择合适的入口&quot;">​</a></h2><table tabindex="0"><thead><tr><th>你的问题</th><th>先用哪个入口</th><th>成功判据</th></tr></thead><tbody><tr><td>我想系统了解项目</td><td>Docs</td><td>找到结构化文档，并能从引用回到源码</td></tr><tr><td>我知道一个函数名或错误文字</td><td>关键词搜索</td><td>结果显示相关路径和内容片段</td></tr><tr><td>我只知道概念，不知道源码用词</td><td>语义或混合搜索</td><td>结果相关，且页面没有未处理的降级提示</td></tr><tr><td>我需要综合多个来源</td><td>Docs 中的项目问答</td><td>回答包含可以打开的项目引用</td></tr></tbody></table><p>三种入口都没有结果时，回到运行详情检查生成文档、搜索索引和警告，而不是重复提交相同查询。</p>',29)])])}const _=a(r,[["render",d]]);export{u as __pageData,_ as default};
